1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials", expression = "java(initials(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
35	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * The owner's age band, derived from the supplied birthDate as at the
44	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
45	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
46	     * available, so the field is omitted for owners without a supplied birth date.
47	     */
48	    default String ageBand(Owner owner) {
49	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
50	            return null;
51	        }
52	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
53	        if (age < 18) {
54	            return "MINOR";
55	        }
56	        if (age < 65) {
57	            return "ADULT";
58	        }
59	        return "SENIOR";
60	    }
61	
62	    /**
63	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
64	     * otherwise 'PHONE'.
65	     */
66	    default String contactPreference(Owner owner) {
67	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
68	        return hasEmail ? "EMAIL" : "PHONE";
69	    }
70	
71	    /**
72	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
73	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
74	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
75	     */
76	    default String locality(Owner owner) {
77	        String code = owner.getCustomerCode();
78	        if (code != null) {
79	            int dash = code.indexOf('-');
80	            if (dash > 0) {
81	                return code.substring(0, dash);
82	            }
83	        }
84	        return "UNKNOWN";
85	    }
86	
87	    /**
88	     * The owner's numeric membership level. It starts at 1, gains 1 when an email address
89	     * is present, gains 1 when the owner has no namesakes (namesakeCount is 0), and gains 1
90	     * when the owner's tenure exceeds 365 days (more than 365 whole days between the
91	     * registrationDate and today), capped at 4. Because a newly created owner has zero
92	     * tenure, a new owner never exceeds level 3; level 4 requires tenure of more than 365
93	     * days.
94	     */
95	    default Integer membershipLevel(Owner owner) {
96	        int level = 1;
97	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
98	        if (hasEmail) {
99	            level++;
100	        }
101	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
102	        if (noNamesakes) {
103	            level++;
104	        }
105	        if (owner.getRegistrationDate() != null
106	            && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(),
107	                java.time.LocalDate.now()) > 365) {
108	            level++;
109	        }
110	        return Math.min(level, 4);
111	    }
112	
113	    /**
114	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
115	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
116	     */
117	    default Integer checkDigit(Owner owner) {
118	        if (owner.getCustomerCode() == null) {
119	            return null;
120	        }
121	        String s = owner.getCustomerCode();
122	        int sum = 0;
123	        boolean dbl = true;
124	        for (int i = s.length() - 1; i >= 0; i--) {
125	            char c = s.charAt(i);
126	            if (c < '0' || c > '9') {
127	                continue;
128	            }
129	            int d = c - '0';
130	            if (dbl) {
131	                d *= 2;
132	                if (d > 9) {
133	                    d -= 9;
134	                }
135	            }
136	            sum += d;
137	            dbl = !dbl;
138	        }
139	        return (10 - (sum % 10)) % 10;
140	    }
141	
142	    /**
143	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
144	     * is the last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
145	     */
146	    default String membershipNumber(Owner owner) {
147	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
148	            return null;
149	        }
150	        return String.format("%s-M%02d", owner.getCustomerCode(),
151	            owner.getRegistrationDate().getYear() % 100);
152	    }
153	
154	    /**
155	     * Known E.164 country calling codes used to split the stored telephone into its
156	     * country code and national number for display. Longer codes are matched first so a
157	     * '+61' number is not mistaken for a '+6...' one.
158	     */
159	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
160	
161	    /**
162	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
163	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
164	     * Returns the stored value unchanged when it is {@code null} or not in the expected
165	     * '+'-prefixed all-digits E.164 form.
166	     */
167	    default String telephoneDisplay(Owner owner) {
168	        String telephone = owner.getTelephone();
169	        if (telephone == null || !telephone.startsWith("+")) {
170	            return telephone;
171	        }
172	        String digits = telephone.substring(1);
173	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
174	            return telephone;
175	        }
176	        String countryCode = COUNTRY_CODES.stream()
177	            .filter(digits::startsWith)
178	            .findFirst()
179	            .orElse(digits.substring(0, 1));
180	        String national = digits.substring(countryCode.length());
181	        StringBuilder sb = new StringBuilder("+").append(countryCode);
182	        for (int i = 0; i < national.length(); i++) {
183	            if (i % 3 == 0) {
184	                sb.append(' ');
185	            }
186	            sb.append(national.charAt(i));
187	        }
188	        return sb.toString();
189	    }
190	
191	    /**
192	     * The upper-cased first letters of firstName and lastName, dot-separated with a
193	     * trailing dot, e.g. 'J.S.'.
194	     */
195	    default String initials(Owner owner) {
196	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
197	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
198	    }
199	
200	    /**
201	     * A stable identifier for the owner's household, derived deterministically from the
202	     * normalized last name and the postcode. Every owner sharing the same last name
203	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
204	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
205	     * '&lt;normalizedLastName&gt;|&lt;postcode&gt;'. A {@code null} postcode contributes
206	     * the empty string.
207	     */
208	    default String householdId(Owner owner) {
209	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
210	        String key = normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
